INSERT INTO challenges (id, category_id, title, description, char_limit, release_date, answer_count, status) VALUES
('c1111111-1111-1111-1111-111111111111', 'aaaaaaaa-aaaa-aaaa-aaaa-aaaaaaaaaaaa', '月曜日の朝を一言で表すと？', '誰もが経験する月曜の朝。あなたならどう表現しますか？', 30, '2024-01-15', 45, 'active'),
('c2222222-2222-2222-2222-222222222222', 'bbbbbbbb-bbbb-bbbb-bbbb-bbbbbbbbbbbb', '「好き」を「好き」を使わずに伝えてください', '直接的な言葉を使わずに、想いを届ける挑戦です。', 30, '2024-01-16', 78, 'active'),
('c3333333-3333-3333-3333-333333333333', 'cccccccc-cccc-cccc-cccc-cccccccccccc', 'おじいちゃんにスマホを説明してください', '世代を超えて伝わる説明力が試されます。', 30, '2024-01-17', 62, 'active'),
('c4444444-4444-4444-4444-444444444444', 'dddddddd-dddd-dddd-dddd-dddddddddddd', '「時間」とは何か、一文で答えよ', '哲学的な問いに、あなたなりの答えを。', 40, '2024-01-18', 34, 'active'),
