INSERT INTO answers (id, challenge_id, user_id, content, score, ai_feedback, like_count, comment_count, view_count, status) VALUES
('a1111111-1111-1111-1111-111111111111', 'c1111111-1111-1111-1111-111111111111', '11111111-1111-1111-1111-111111111111', '布団が恋人から敵に変わる瞬間。', 85, '{"creativity": 90, "expression": 80, "impact": 85, "comment": "ユーモアと共感が絶妙にマッチしています"}', 34, 5, 120, 'active'),
('a2222222-2222-2222-2222-222222222222', 'c1111111-1111-1111-1111-111111111111', '22222222-2222-2222-2222-222222222222', '一週間の序章、希望と絶望の狭間。', 78, '{"creativity": 75, "expression": 82, "impact": 77, "comment": "詩的な表現が印象的です"}', 21, 3, 89, 'active'),
('a3333333-3333-3333-3333-333333333333', 'c2222222-2222-2222-2222-222222222222', '33333333-3333-3333-3333-333333333333', 'あなたの名前を呼ぶとき、心が温かくなる。', 92, '{"creativity": 88, "expression": 95, "impact": 93, "comment": "シンプルながら心に響く表現です"}', 67, 12, 234, 'active'),
('a4444444-4444-4444-4444-444444444444', 'c3333333-3333-3333-3333-333333333333', '55555555-5555-5555-5555-555555555555', '世界中の人と手紙を瞬時に交換できる魔法の板。', 88, '{"creativity": 92, "expression": 85, "impact": 87, "comment": "比喩が秀逸で理解しやすい"}', 45, 8, 156, 'active'),
('a5555555-5555-5555-5555-555555555555', 'c4444444-4444-4444-4444-444444444444', '33333333-3333-3333-3333-333333333333', '時間とは、人生という砂時計を落ちていく砂の一粒一粒。', 94, '{"creativity": 95, "expression": 93, "impact": 94, "comment": "深い洞察と美しい表現の融合"}', 89, 15, 312, 'active'),
('a6666666-6666-6666-6666-666666666666', 'c5555555-5555-5555-5555-555555555555', '22222222-2222-2222-2222-222222222222', '透明な一口が、心まで澄み渡る。', 91, '{"creativity": 88, "expression": 94, "impact": 91, "comment": "商品特性を見事に捉えたコピー"}', 56, 7, 178, 'active'),
('a7777777-7777-7777-7777-777777777777', 'c5555555-5555-5555-5555-555555555555', '11111111-1111-1111-1111-111111111111', 'この透明、嘘がない。', 87, '{"creativity": 90, "expression": 85, "impact": 86, "comment": "短くインパクトがあります"}', 38, 4, 134, 'active'),
('a8888888-8888-8888-8888-888888888888', 'c6666666-6666-6666-6666-666666666666', '44444444-4444-4444-4444-444444444444', '知らない子供が窓の外に手を振ってくれた。', 82, '{"creativity": 78, "expression": 85, "impact": 83, "comment": "日常の温かさが伝わります"}', 28, 6, 98, 'active');
